<?php
namespace App\Controllers\Api;
use App\Controllers\BaseController;use App\Models\PortalModel;use App\Libraries\WhatsappGateway;
class AdminController extends BaseController {
 private function guard(){return $this->requireAdmin()?null:$this->json(['success'=>false,'message'=>'Unauthorized'],401);}
 public function login(){$d=$this->request->getJSON(true)?:$this->request->getPost();$r=db_connect()->table('admins')->where('username',trim((string)($d['username']??'')))->get()->getRowArray();if(!$r||!password_verify((string)($d['password']??''),$r['password_hash']))return $this->json(['success'=>false,'message'=>'Username atau password salah.'],401);session()->regenerate(true);session()->set('admin',['id'=>$r['id'],'username'=>$r['username']]);return $this->json(['success'=>true]);}
 public function logout(){session()->remove('admin');session()->regenerate(true);return $this->json(['success'=>true]);}
 public function status(){return $this->guard()??$this->json(['success'=>true,'admin'=>session('admin')]);}
 public function settings(){if($r=$this->guard())return $r;$m=new PortalModel();return $this->json(['appName'=>$m->setting('app_name','Pesona Wifi'),'appUrl'=>$m->setting('app_url',''),'logoUrl'=>$m->setting('logo_url'),'genieacsUrl'=>$m->setting('genieacs_url',''),'ssidIndexes'=>json_decode($m->setting('ssid_indexes','[1,5]'),true)]);}
 public function saveSettings(){if($r=$this->guard())return $r;$d=$this->request->getJSON(true)?:$this->request->getPost();$m=new PortalModel();foreach(['appName'=>'app_name','appUrl'=>'app_url','genieacsUrl'=>'genieacs_url','ssidIndexes'=>'ssid_indexes'] as $k=>$s)if(array_key_exists($k,$d))$m->saveSetting($s,is_array($d[$k])?json_encode($d[$k]):(string)$d[$k]);$m->log('settings.updated',session('admin.username'),$d);return $this->json(['success'=>true]);}
 public function uploadLogo(){if($r=$this->guard())return $r;$f=$this->request->getFile('logo');if(!$f||!$f->isValid()||$f->getSizeByUnit('mb')>2)return $this->json(['success'=>false,'message'=>'File tidak valid atau lebih dari 2 MB.'],422);$mime=$f->getMimeType();$extensions=['image/png'=>'png','image/jpeg'=>'jpg','image/gif'=>'gif','image/webp'=>'webp'];if(!isset($extensions[$mime]))return $this->json(['success'=>false,'message'=>'Format tidak didukung.'],422);$n='logo_'.bin2hex(random_bytes(8)).'.'.$extensions[$mime];$f->move(FCPATH.'uploads',$n);$url='/uploads/'.$n;(new PortalModel())->saveSetting('logo_url',$url);return $this->json(['success'=>true,'logoUrl'=>$url]);}
 public function deleteLogo(){if($r=$this->guard())return $r;$m=new PortalModel();$old=$m->setting('logo_url');if($old&&str_starts_with($old,'/uploads/'))@unlink(FCPATH.ltrim($old,'/'));$m->saveSetting('logo_url',null);return $this->json(['success'=>true]);}
 public function credentials(){if($r=$this->guard())return $r;$d=$this->request->getJSON(true)?:$this->request->getPost();$a=session('admin');$row=db_connect()->table('admins')->where('id',$a['id'])->get()->getRowArray();if(!$row||!password_verify((string)($d['currentPassword']??''),$row['password_hash']))return $this->json(['success'=>false,'message'=>'Password saat ini salah.'],422);$u=trim((string)($d['username']??$row['username']));$up=['username'=>$u];if(!empty($d['newPassword'])){if(strlen($d['newPassword'])<8)return $this->json(['success'=>false,'message'=>'Password minimal 8 karakter.'],422);$up['password_hash']=password_hash($d['newPassword'],PASSWORD_DEFAULT);}db_connect()->table('admins')->where('id',$row['id'])->update($up);session()->set('admin.username',$u);return $this->json(['success'=>true]);}
 public function customers(){if($r=$this->guard())return $r;return $this->json(['success'=>true,'customers'=>db_connect()->table('customers')->orderBy('id','DESC')->get()->getResultArray()]);}
 public function logs(){if($r=$this->guard())return $r;return $this->json(['success'=>true,'logs'=>db_connect()->table('audit_logs')->orderBy('id','DESC')->limit(100)->get()->getResultArray()]);}
 public function whatsappStatus(){if($r=$this->guard())return $r;return $this->json((new WhatsappGateway())->status());}
}